/** Leo Night in-call screen. Demo never obtains a Call or changes system audio. */
public final class InCallActivity extends LeoActivity {
    static boolean visible;
    private Face face;
    private final Handler clock=new Handler();
    private boolean demo,demoMute,demoSpeaker;
    private int demoState=Call.STATE_RINGING,selected;
    private long demoConnected;
    private Call toneCall;
    private char tone;
    private String lookupNumber="",contact="";private Bitmap contactPhoto;
    private final BroadcastReceiver changed=new BroadcastReceiver(){public void onReceive(Context c,Intent i){refresh();}};
    private final Runnable tick=new Runnable(){public void run(){refresh();}};
    protected void onDestroy(){if(contactPhoto!=null){contactPhoto.recycle();contactPhoto=null;}clock.removeCallbacksAndMessages(null);super.onDestroy();}
    protected void onCreate(Bundle b){super.onCreate(b);demo=getIntent().getBooleanExtra("demo",false);if(b!=null){demoState=b.getInt("state",Call.STATE_RINGING);demoMute=b.getBoolean("mute");demoSpeaker=b.getBoolean("speaker");demoConnected=b.getLong("connected",0);}
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        face=new Face();setContentView(face);
    }
    protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);demo=i.getBooleanExtra("demo",false);refresh();}
    protected void onResume(){super.onResume();visible=true;LeoPointerService.prepareForCall();registerReceiver(changed,new IntentFilter(LeoInCallService.CHANGED));clock.removeCallbacks(tick);clock.post(tick);}
    protected void onPause(){visible=false;unregisterReceiver(changed);clock.removeCallbacks(tick);stopTone();super.onPause();}
    protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putInt("state",demoState);b.putBoolean("mute",demoMute);b.putBoolean("speaker",demoSpeaker);b.putLong("connected",demoConnected);}
    private Call call(){return demo?null:LeoInCallService.current();}
    private int state(){Call c=call();return demo?demoState:c==null?Call.STATE_DISCONNECTED:c.getState();}
    private boolean muted(){LeoInCallService s=LeoInCallService.active;return demo?demoMute:s!=null&&s.getCallAudioState()!=null&&s.getCallAudioState().isMuted();}
    private int route(){LeoInCallService s=LeoInCallService.active;return demo?(demoSpeaker?CallAudioState.ROUTE_SPEAKER:CallAudioState.ROUTE_EARPIECE):s==null||s.getCallAudioState()==null?0:s.getCallAudioState().getRoute();}
    private String routeName(int route){return (route&CallAudioState.ROUTE_BLUETOOTH)!=0?"Bluetooth":(route&CallAudioState.ROUTE_SPEAKER)!=0?"Difuzor":(route&CallAudioState.ROUTE_WIRED_HEADSET)!=0?"Căști cu fir":route==0?"Se verifică":"Receptor";}
    private void refresh(){if(face==null)return;Call c=call();String number=LeoInCallService.number(c);if(!demo&&!number.isEmpty()&&!number.equals(lookupNumber)){lookupNumber=number;contact="";final String wanted=number;worker.execute(new Runnable(){public void run(){String found="";Bitmap photo=null;try(android.database.Cursor row=getContentResolver().query(android.net.Uri.withAppendedPath(ContactsContract.PhoneLookup.CONTENT_FILTER_URI,android.net.Uri.encode(wanted)),new String[]{ContactsContract.PhoneLookup.DISPLAY_NAME,ContactsContract.PhoneLookup.PHOTO_URI},null,null,null)){if(row!=null&&row.moveToFirst()){found=row.getString(0);String uri=row.getString(1);if(uri!=null)try{photo=Appearance.decode(InCallActivity.this,android.net.Uri.parse(uri),96);}catch(Exception ignored){}}}catch(RuntimeException ignored){}final String result=found;final Bitmap avatar=photo;ui(new Runnable(){public void run(){if(wanted.equals(lookupNumber)){contact=result==null?"":result;if(contactPhoto!=null)contactPhoto.recycle();contactPhoto=avatar;face.invalidate();}else if(avatar!=null){avatar.recycle();}}});}});}if(number.isEmpty()&&!lookupNumber.isEmpty()){lookupNumber="";contact="";if(contactPhoto!=null){contactPhoto.recycle();contactPhoto=null;}}
        clock.removeCallbacks(tick);if(state()==Call.STATE_ACTIVE||state()==Call.STATE_HOLDING)clock.postDelayed(tick,1000);face.invalidate();
        if(!demo&&c==null)clock.postDelayed(new Runnable(){public void run(){if(!demo&&LeoInCallService.current()==null)finish();}},2200);
    }
    private void answer(){if(demo){demoState=Call.STATE_ACTIVE;demoConnected=System.currentTimeMillis();}else{Call c=call();if(c!=null&&c.getState()==Call.STATE_RINGING)c.answer(VideoProfile.STATE_AUDIO_ONLY);}selected=0;refresh();}
    private void end(){stopTone();if(demo)demoState=Call.STATE_DISCONNECTED;else{Call c=call();if(c!=null){if(c.getState()==Call.STATE_RINGING)c.reject(false,null);else c.disconnect();}else finish();}refresh();}
    private void mute(){if(demo)demoMute=!demoMute;else if(LeoInCallService.active!=null)LeoInCallService.active.setMuted(!muted());refresh();}
    private void routes(){if(demo){options("Ieșire audio · DEMO",new String[]{"Receptor","Difuzor"},new Choice(){public void pick(int i){demoSpeaker=i==1;refresh();}});return;}final LeoInCallService s=LeoInCallService.active;if(s==null||s.getCallAudioState()==null){notice("Ieșirea audio nu este încă disponibilă");return;}int mask=s.getCallAudioState().getSupportedRouteMask();final ArrayList<Integer> ids=new ArrayList<Integer>();ArrayList<String> names=new ArrayList<String>();for(int id:new int[]{CallAudioState.ROUTE_EARPIECE,CallAudioState.ROUTE_WIRED_HEADSET,CallAudioState.ROUTE_BLUETOOTH,CallAudioState.ROUTE_SPEAKER})if((mask&id)!=0){ids.add(id);names.add(routeName(id));}options("Ieșire audio",names.toArray(new String[0]),new Choice(){public void pick(int i){if(LeoInCallService.active==s)s.setAudioRoute(ids.get(i));}});}
    private void hold(){if(demo){demoState=demoState==Call.STATE_HOLDING?Call.STATE_ACTIVE:Call.STATE_HOLDING;refresh();return;}Call c=call();if(c==null)return;if(c.getState()==Call.STATE_HOLDING)c.unhold();else if(c.getDetails()!=null&&c.getDetails().can(Call.Details.CAPABILITY_HOLD))c.hold();else notice("Rețeaua nu oferă punerea în așteptare");}
    private void menu(){if(state()==Call.STATE_DISCONNECTED){finish();return;}options(demo?"Apel · DEMO":"Apel Leo",new String[]{state()==Call.STATE_RINGING?"Răspunde":muted()?"Pornește microfonul":"Oprește microfonul","Ieșire audio",state()==Call.STATE_HOLDING?"Reia apelul":"Pune în așteptare","Apeluri și conferință","Taste DTMF · 0–9, * și #","Închide apelul"},new Choice(){public void pick(int i){if(i==0){if(state()==Call.STATE_RINGING)answer();else mute();}else if(i==1)routes();else if(i==2)hold();else if(i==3)otherCalls();else if(i==4)notice("În convorbire, cifrele fizice trimit DTMF. Tonul se oprește la eliberarea tastei.");else end();}});}
    private void otherCalls(){if(demo){notice("DEMO · un singur apel local");return;}final List<Call> all=LeoInCallService.calls();ArrayList<String> names=new ArrayList<String>();for(Call c:all)names.add(LeoInCallService.identity(c)+" · "+CallPresentation.state(c.getState()));options("Apeluri · "+all.size(),names.toArray(new String[0]),new Choice(){public void pick(int i){LeoInCallService.select(all.get(i));refresh();Call c=call();if(c==null||c.getDetails()==null)return;final Call chosen=c;if(chosen.getDetails().can(Call.Details.CAPABILITY_MERGE_CONFERENCE)&&!chosen.getConferenceableCalls().isEmpty())options("Conferință",new String[]{"Păstrează separat","Unește apelurile"},new Choice(){public void pick(int n){if(n==1&&!chosen.getConferenceableCalls().isEmpty())chosen.conference(chosen.getConferenceableCalls().get(0));}});else if(chosen.getDetails().can(Call.Details.CAPABILITY_SWAP_CONFERENCE))options("Conferință",new String[]{"Păstrează","Schimbă interlocutorul"},new Choice(){public void pick(int n){if(n==1)chosen.swapConference();}});}});}
    private void stopTone(){if(toneCall!=null)toneCall.stopDtmfTone();toneCall=null;tone=0;if(face!=null)face.invalidate();}
    public boolean dispatchKeyEvent(KeyEvent e){if(LeoActivity.isJackNavigationNoise(e))return true;int k=e.getKeyCode();char digit=k>=KeyEvent.KEYCODE_0&&k<=KeyEvent.KEYCODE_9?(char)('0'+k-KeyEvent.KEYCODE_0):k==KeyEvent.KEYCODE_STAR?'*':k==KeyEvent.KEYCODE_POUND?'#':0;if(digit!=0){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0&&state()==Call.STATE_ACTIVE){stopTone();tone=digit;if(!demo){toneCall=call();if(toneCall!=null)toneCall.playDtmfTone(digit);}face.invalidate();}else if(e.getAction()==KeyEvent.ACTION_UP)stopTone();return true;}return super.dispatchKeyEvent(e);}
    public boolean onKeyDown(int key,KeyEvent e){if(e.getRepeatCount()>0)return key==KeyEvent.KEYCODE_MENU||key==KeyEvent.KEYCODE_CALL||key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||super.onKeyDown(key,e);if(key==KeyEvent.KEYCODE_BACK||key==KeyEvent.KEYCODE_ENDCALL){if(state()==Call.STATE_DISCONNECTED)finish();else end();return true;}if(key==KeyEvent.KEYCODE_CALL){if(state()==Call.STATE_RINGING)answer();else if(state()==Call.STATE_HOLDING)hold();return true;}if(key==KeyEvent.KEYCODE_MENU){if(state()==Call.STATE_RINGING)answer();else menu();return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){selected=1-selected;face.invalidate();return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(state()==Call.STATE_DISCONNECTED)finish();else if(state()==Call.STATE_RINGING){if(selected==0)answer();else end();}else if(selected==0)mute();else routes();return true;}if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){if(!demo)((AudioManager)getSystemService(AUDIO_SERVICE)).adjustStreamVolume(AudioManager.STREAM_VOICE_CALL,key==KeyEvent.KEYCODE_DPAD_UP?AudioManager.ADJUST_RAISE:AudioManager.ADJUST_LOWER,AudioManager.FLAG_SHOW_UI);else notice("DEMO · volumul telefonului nu se schimbă");return true;}return super.onKeyDown(key,e);}
    public void onBackPressed(){if(state()==Call.STATE_DISCONNECTED)finish();else end();}
    private final class Face extends View {
        final Paint p=new Paint(3);Face(){super(InCallActivity.this);setFocusable(true);requestFocus();}
        void text(Canvas c,String s,float x,float y,int size,int color){p.setStyle(Paint.Style.FILL);p.setColor(color);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextSize(size);p.setTextAlign(Paint.Align.CENTER);if(s==null)s="";if(p.measureText(s)>216){int n=p.breakText(s,true,216-p.measureText("…"),null);s=s.substring(0,n)+"…";}c.drawText(s,x,y,p);}
        protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/302f);c.drawColor(palette.background);p.setColor(palette.bar);c.drawRect(0,0,240,37,p);text(c,demo?"Telefon · DEMO":"Telefon Leo",120,26,20,Color.WHITE);p.setColor(palette.accent);c.drawRect(0,37,240,39,p);int state=state();Call call=call();String name=demo?"Ana":!contact.isEmpty()?contact:LeoInCallService.identity(call);String number=demo?"Fără apel real":LeoInCallService.number(call);p.setColor(0xffee657a);c.drawCircle(120,77,26,p);if(contactPhoto!=null&&!demo){c.save();Path clip=new Path();clip.addCircle(120,77,26,Path.Direction.CW);c.clipPath(clip);c.drawBitmap(contactPhoto,null,new RectF(94,51,146,103),p);c.restore();}else text(c,name.isEmpty()?"?":name.substring(0,1).toUpperCase(java.util.Locale.ROOT),120,87,28,Color.WHITE);text(c,name,120,125,22,Color.WHITE);text(c,number.equals(name)?"":number,120,145,12,0xffb8bad0);text(c,CallPresentation.state(state),120,172,17,palette.accent);long connect=demo?demoConnected:call==null||call.getDetails()==null?0:call.getDetails().getConnectTimeMillis();text(c,state==Call.STATE_ACTIVE||state==Call.STATE_HOLDING?CallPresentation.duration(connect<=0?0:System.currentTimeMillis()-connect):state==Call.STATE_DISCONNECTED?(demo?"Demo încheiat":LeoInCallService.lastEnd):"",120,197,state==Call.STATE_DISCONNECTED?12:23,state==Call.STATE_DISCONNECTED?0xffb8bad0:palette.accent);text(c,demo?"SIM · demonstrație":call==null?"":LeoInCallService.account(InCallActivity.this,call),120,215,12,0xffb8bad0);
            for(int i=0;i<2;i++){float left=10+i*116;p.setStyle(Paint.Style.FILL);p.setColor(palette.card);c.drawRoundRect(left,225,left+104,271,4,4,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(i==selected?2:1);p.setColor(i==selected?palette.accent:0xff3a3d55);c.drawRoundRect(left,225,left+104,271,4,4,p);text(c,state==Call.STATE_RINGING?(i==0?"Răspunde":"Respinge"):(i==0?"Microfon":"Ieșire audio"),left+52,245,13,state==Call.STATE_RINGING&&i==1?0xffff7e91:Color.WHITE);text(c,state==Call.STATE_RINGING?(i==0?"Verde / OK":"Soft dreapta"):(i==0?muted()?"Oprit":"Pornit":routeName(route())),left+52,262,11,palette.accent);}
            p.setStyle(Paint.Style.FILL);p.setColor(palette.bar);c.drawRect(0,278,240,302,p);text(c,state==Call.STATE_RINGING?"Răspunde":"Opțiuni",36,295,11,Color.WHITE);text(c,tone!=0?"DTMF · "+tone:state==Call.STATE_DISCONNECTED?"Gata":"Alege",120,295,12,palette.accent);text(c,state==Call.STATE_RINGING?"Respinge":"Închide",204,295,11,Color.WHITE);c.restore();
        }
    }
}
